package ais.action.master.generic.v2.test;import java.util.Calendar;import java.util.HashSet;import ais.common.newui.lkp.NewUiWorkRealizationService;import ais.common.newui.lkp.NewUiWorkRealizationService.Filter;import ais.common.newui.lkp.NewUiWorkRealizationService.Snapshot;import ais.database.model.lkp.KegiatanTugasJabatan;import ais.database.model.rab.SatuanKerja;public final class WorkRealizationDatabaseSelfTest{private WorkRealizationDatabaseSelfTest(){}public static void main(String[]a){System.setProperty("javax.persistence.validation.mode","none");System.setProperty("hibernate.validator.apply_to_ddl","false");Calendar now=Calendar.getInstance();Filter f=new Filter();f.year=now.get(Calendar.YEAR);f.month=Integer.valueOf(now.get(Calendar.MONTH));f.period=KegiatanTugasJabatan.BULANAN;f.page=0;f.size=10;Snapshot s=new NewUiWorkRealizationService().load(f,new HashSet<SatuanKerja>(),null);check(s.total>=0&&s.rows.size()<=10,"rows");check(s.employees!=null&&s.units!=null,"options");System.out.println("WorkRealizationDatabaseSelfTest OK total="+s.total);System.exit(0);}private static void check(boolean v,String m){if(!v)throw new IllegalStateException(m);}}
